command:
cat > /etc/nginx/sites-available/fleet-tls <<'EOF'
server {
    listen 8443 ssl default_server;
    server_name node2;

    ssl_certificate     /etc/ssl/fleet-tls/node2.cert.pem;
    ssl_certificate_key /etc/ssl/fleet-tls/node2.key.pem;

    location / {
        root /var/www/html;
        index index.nginx-debian.html;
    }
}
EOF
ln -sf /etc/nginx/sites-available/fleet-tls /etc/nginx/sites-enabled/fleet-tls
nginx -t 2>&1
systemctl reload nginx 2>&1 || systemctl restart nginx 2>&1
systemctl is-active nginx

